       subtitle = "Estados Unidos") +
  theme(plot.title = element_text(hjust = 0.5, size = 14, face = "bold", color = "darkgreen"),
        plot.subtitle = element_text(hjust = 0.5, size = 12, face = "italic", color = "blue"))
