  geom_point(size = 3) +
  labs(title = "PIB per capita e população", 
       subtitle = "Estados Unidos",
       x = "PIB per capita",
       y = "População",
       color = "Ano") +
  theme(axis.text.x = element_text(angle = 45, hjust = 1, size = 14),
  axis.text.y = element_text(angle = 45, hjust = 1, size = 14))
