#### Scalas



::: {.cell}

```{.r .cell-code}
df13.1 <- dados %>% 
  filter(year == 2007 & pop >= 190000000)

ggplot(df13.1, aes(x = gdpPercap, y = lifeExp, shape = country)) +
  geom_point(size = 6, color = "green") +
  labs(title = "PIB per capita e expectativa de vida nos países com mais de 190000000 pessoas em 2007",
       x = "PIB per capita",
       y = "Expectativa de vida",
       shape = "País")
```

::: {.cell-output-display}
![](ggplot2_files/figure-html/unnamed-chunk-28-1.png){width=672}
:::

```{.r .cell-code}
# Ajustando escalas dos eixos x e y
ggplot(df13.1, aes(x = gdpPercap, y = lifeExp, shape = country)) +
  geom_point(size = 6, color = "green") +
  labs(title = "PIB per capita e expectativa de vida nos países com mais de 190000000 pessoas em 2007",
       x = "PIB per capita",
       y = "Expectativa de vida",
       shape = "País") +
  scale_y_continuous(limits = c(60, 85)) +
  scale_x_continuous(limits = c(0, 50000))
```

::: {.cell-output-display}
![](ggplot2_files/figure-html/unnamed-chunk-28-2.png){width=672}
:::

```{.r .cell-code}
# Ajustando escalas dos eixos x e y - definindo intervalos
ggplot(df13.1, aes(x = gdpPercap, y = lifeExp, shape = country)) +
  geom_point(size = 6, color = "green") +
  labs(title = "PIB per capita e expectativa de vida nos países com mais de 190000000 pessoas em 2007",
       x = "PIB per capita",
       y = "Expectativa de vida",
       shape = "País") +
  scale_y_continuous(limits = c(60, 85), breaks = seq(60, 85, by = 2.5)) +
  scale_x_continuous(limits = c(0, 50000), breaks = seq(0, 50000, by = 10000))
```

::: {.cell-output-display}
![](ggplot2_files/figure-html/unnamed-chunk-28-3.png){width=672}
